/*
 * Compatibility stand-in, not GSAP. Pages generated by earlier versions of
 * nr_landingpage load this path and run scripts stored in the page that call
 * GSAP: the animation script the extension generated and, in creative mode,
 * scripts the LLM wrote. GSAP is no longer shipped (see Documentation/Usage).
 *
 * This object accepts every call without animating, so a stored script does
 * not stop at an unknown method. Where a call names an end state that decides
 * whether content is seen, it applies that state at once: opacity, autoAlpha,
 * visibility and text (string or {value}) of to(), fromTo() and set(), also on
 * timelines. Callbacks passed to matchMedia().add() and to ScrollTrigger's
 * create() and batch() run once. Everything else does nothing.
 */
(function () {
  'use strict';

  // A value that can be called, read and iterated without throwing.
  var inert = new Proxy(function () {}, {
    get: function (target, property) {
      if (property === 'then') {
        return undefined;
      }
      if (property === Symbol.toPrimitive) {
        return function () { return 0; };
      }
      if (property === Symbol.iterator) {
        return function () { return [][Symbol.iterator](); };
      }
      return inert;
    },
    apply: function () {
      return inert;
    }
  });

  function permissive(object) {
    return new Proxy(object, {
      get: function (target, property) {
        return property in target ? target[property] : inert;
      }
    });
  }

  function elements(target) {
    if (typeof target === 'string') {
      try {
        return Array.prototype.slice.call(document.querySelectorAll(target));
      } catch (e) {
        return [];
      }
    }
    if (target && target.nodeType === 1) {
      return [target];
    }
    if (target && typeof target.length === 'number' && target !== inert) {
      return Array.prototype.slice.call(target).filter(function (element) {
        return element && element.nodeType === 1;
      });
    }
    return [];
  }

  function applyEndState(target, vars) {
    if (!vars || typeof vars !== 'object') {
      return;
    }
    var text = vars.text;
    if (text && typeof text === 'object') {
      text = text.value;
    }
    elements(target).forEach(function (element) {
      if (typeof text === 'string') {
        element.textContent = text;
      }
      if (vars.autoAlpha !== undefined) {
        element.style.opacity = String(vars.autoAlpha);
        element.style.visibility = Number(vars.autoAlpha) > 0 ? 'visible' : 'hidden';
      }
      if (vars.opacity !== undefined) {
        element.style.opacity = String(vars.opacity);
      }
      if (typeof vars.visibility === 'string') {
        element.style.visibility = vars.visibility;
      }
    });
  }

  function run(callback, argument) {
    if (typeof callback === 'function') {
      try {
        callback(argument);
      } catch (e) {
        // A failing callback must not stop the rest of the stored script.
      }
    }
  }

  function tweens(owner) {
    owner.to = function (target, vars) { applyEndState(target, vars); return owner.self; };
    owner.set = function (target, vars) { applyEndState(target, vars); return owner.self; };
    owner.fromTo = function (target, fromVars, toVars) { applyEndState(target, toVars); return owner.self; };
    owner.from = function () { return owner.self; };
    return owner;
  }

  function timeline() {
    var owner = tweens({});
    owner.self = permissive(owner);
    return owner.self;
  }

  var gsap = tweens({
    registerPlugin: function () {},
    matchMedia: function () {
      return permissive({
        add: function (query, callback) { run(callback, inert); return inert; }
      });
    },
    timeline: timeline,
    utils: permissive({
      toArray: function (target) { return elements(target); }
    })
  });
  gsap.self = inert;
  window.gsap = permissive(gsap);
})();
